beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant(\"imports\");
  registerEventHandlers();
});
beforeEach(() => resetRateLimits());
afterAll(() => { unregisterEventHandlers(); cleanup(); });

describe(\"bulk issue import\", () => {
  it(\"preserves rows and numbering, resolves active assignees and workspace labels, and announces only the batch\", async () => {
    const other = await createTenant(\"imports-other\");
    const db = getDb();
    const stamp = tenant.org.createdAt;
    db.insert(labels).values({ id: \"other-label\", orgId: other.org.id, name: \"Shared\", color: \"#ffffff\", createdAt: stamp, updatedAt: stamp }).run();
    db.insert(labels).values({ id: \"own-label\", orgId: tenant.org.id, name: \"Existing\", color: \"#ffffff\", createdAt: stamp, updatedAt: stamp }).run();
    db.update(members).set({ archivedAt: stamp }).where(and(eq(members.orgId, tenant.org.id), eq(members.userId, tenant.userIds.viewer))).run();
    const preceding = await createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id));
    await archiveIssue(tenant.actors.member, tenant.org.id, preceding.id);
    db.insert(webhookEndpoints).values({ id: \"import-hook\", orgId: tenant.org.id, url: \"https://example.test/hook\", secret: \"secret\", eventTypes: JSON.stringify([\"issue.created\", \"issues.imported\"]), createdAt: stamp, updatedAt: stamp }).run();
    const created: unknown[] = [];
    const batches: unknown[] = [];
    const offCreate = subscribe(\"issue.created\", (p) => { created.push(p); });
    const offImport = subscribe(\"issues.imported\", (p) => { batches.push(p); });
    try {
      const before = await usageRepo.getUsage(tenant.org.id);
      const result = await importIssues(tenant.actors.member, input(tenant, \"upload-one\", [
        { title: \"First imported\", description: \"Searchable description\", priority: \"urgent\", status: \"done\", dueAt: \"2027-01-01T00:00:00.000Z\", assigneeEmail: \"ADMIN@IMPORTS.TEST\", labels: [\"Shared\", \"Shared\", \"Existing\"] },
        { title: \"Second imported\", assigneeEmail: \"viewer@imports.test\", labels: [\"Shared\", \"shared\"] },
        { title: \"Third imported\", assigneeEmail: \"member@imports-other.test\" },
      ]));
      expect(result.replayed).toBe(false);
      expect(result.issues.map((i) => i.number)).toEqual([2, 3, 4]);
      expect(result.issues[0]).toMatchObject({ title: \"First imported\", description: \"Searchable description\", status: \"done\", priority: \"urgent\", dueAt: \"2027-01-01T00:00:00.000Z\", assigneeId: tenant.userIds.admin, authorId: tenant.userIds.member, parentId: null, estimate: null });
      expect(result.issues[0]?.labelIds).toHaveLength(2);
      expect(result.issues.slice(1).map((i) => i.assigneeId)).toEqual([null, null]);
      expect(db.select().from(labels).where(eq(labels.orgId, tenant.org.id)).all().map((l) => l.name).sort()).toEqual([\"Existing\", \"Shared\", \"shared\"]);
      expect(db.select().from(labels).where(and(eq(labels.orgId, tenant.org.id), eq(labels.name, \"Shared\"))).get()).toMatchObject({ color: \"#94a3b8\", description: null });
      expect(created).toHaveLength(0);
      expect(batches).toEqual([expect.objectContaining({ actorId: tenant.userIds.member, issueIds: result.issues.map((i) => i.id), importKey: \"upload-one\" })]);
      expect(db.select().from(searchIndex).where(eq(searchIndex.orgId, tenant.org.id)).all().filter((s) => result.issues.some((i) => i.id === s.subjectId))).toHaveLength(3);
      expect((await usageRepo.getUsage(tenant.org.id)).issuesUsed).toBe(before.issuesUsed + 3);
      expect((await usageRepo.recomputeUsage(tenant.org.id)).issuesUsed).toBe(before.issuesUsed + 3);
      const audit = db.select().from(activityEvents).where(and(eq(activityEvents.orgId, tenant.org.id), eq(activityEvents.action, \"issues.imported\"))).all();
      expect(audit).toHaveLength(1);
      expect(audit[0]).toMatchObject({ actorId: tenant.userIds.member, subjectKind: \"project\", subjectId: tenant.project.id, projectId: tenant.project.id });
      expect(JSON.parse(audit[0]"'!.metadata)).toEqual({ count: 3, importKey: "upload-one" });
      expect(db.select().from(notifications).where(eq(notifications.orgId, tenant.org.id)).all()).toHaveLength(0);
      expect(db.select().from(webhookDeliveries).where(eq(webhookDeliveries.orgId, tenant.org.id)).all()).toHaveLength(0);
      expect((await createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id))).number).toBe(5);
    } finally { offCreate(); offImport(); }
  });

  it("persists replay results, ignores replacement rows, and scopes keys to the workspace", async () => {
    const original = await importIssues(tenant.actors.member, input(tenant, "replay-key", [{ title: "Original issue" }]));
    expect(getDb().select().from(issueImports).where(eq(issueImports.orgId, tenant.org.id)).all()).toHaveLength(2);
    const seen: unknown[] = [];
    const off = subscribe("issues.imported", (p) => { seen.push(p); });
    try {
      expect(await importIssues(tenant.actors.member, input(tenant, "replay-key", [{ title: "Replacement issue" }]))).toEqual({ ...original, replayed: true });
      expect(seen).toHaveLength(0);
    } finally { off(); }
    const other = await createTenant("replay-other");
    expect((await importIssues(other.actors.member, input(other, "replay-key", [{ title: "Original issue" }]))).replayed).toBe(false);
    expect((await importIssues(tenant.actors.member, input(tenant, "different-key", [{ title: "Original issue" }]))).replayed).toBe(false);
  });

  it("refuses the whole batch at the live issue quota without retaining its key or labels", async () => {
    const t = await createTenant("import-quota", "free");
    for (let n = 1; n <= 99; n++) await issueRepo.insertIssue(issueInput(t.org.id, t.project.id), t.userIds.member, n);
    const batch = input(t, "quota-key", [{ title: "First row", labels: ["Not created"] }, { title: "Second row" }]);
    await expect(importIssues(t.actors.member, batch)).rejects.toThrow(/allows no more issues/);
    expect(await issueRepo.countIssues(t.org.id, t.project.id)).toBe(99);
    expect(issueRepo.findIssueImport(t.org.id, batch.importKey)).toBeNull();
    expect(getDb().select().from(labels).where(eq(labels.orgId, t.org.id)).all()).toHaveLength(0);
    const archived = await issueRepo.findIssueByNumber(t.org.id, t.project.id, 1);
    await issueRepo.archiveIssue(t.org.id, archived!.id);
    expect((await importIssues(t.actors.member, batch)).replayed).toBe(false);
  });

  it("charges the batch rate allowance atomically and permits a refused key to retry", async () => {
    const t = await createTenant("import-rate", "free");
    await consumeRateLimit(t.org.id, "issue:create", 59);
    const batch = input(t, "rate-key", [{ title: "First row" }, { title: "Second row" }]);
    await expect(importIssues(t.actors.member, batch)).rejects.toThrow(/rate limit/);
    expect(await issueRepo.countIssues(t.org.id, t.project.id)).toBe(0);
    expect(issueRepo.findIssueImport(t.org.id, batch.importKey)).toBeNull();
    expect((await consumeRateLimit(t.org.id, "issue:create")).allowed).toBe(true);
    resetRateLimits();
    await importIssues(t.actors.member, batch);
    expect((await consumeRateLimit(t.org.id, "issue:create", 59)).allowed).toBe(false);
  });

  it("applies scope, project lookup, archive and create permission gates", async () => {
    const t = await createTenant("import-access");
    const batch = input(t, "access-key", [{ title: "Never imported" }]);
    await expect(importIssues(tenant.actors.member, batch)).rejects.toBeInstanceOf(TenantScopeError);
    await expect(importIssues(t.actors.viewer, batch)).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(importIssues(t.actors.member, { ...batch, projectId: tenant.project.id })).rejects.toBeInstanceOf(NotFoundError);
    await expect(importIssues(t.actors.member, { ...batch, projectId: "missing" as ProjectId })).rejects.toBeInstanceOf(NotFoundError);
    const { projects } = await import("@/server/db");
    getDb().update(projects).set({ archivedAt: t.org.createdAt }).where(eq(projects.id, t.project.id)).run();
    await expect(importIssues(t.actors.member, batch)).rejects.toBeInstanceOf(AlreadyArchivedError);
    expect(await issueRepo.countIssues(t.org.id, t.project.id)).toBe(0);
  });
});
