    const seen: unknown[] = [];
    const off = subscribe("issues.imported", (p) => { seen.push(p); });
    try {
      expect(await importIssues(tenant.actors.member, input(tenant, "replay-key", [{ title: "Replacement issue" }]))).toEqual({ ...original, replayed: true });
      expect(seen).toHaveLength(0);
    } finally { off(); }
    const other = await createTenant("replay-other");
