    expect(await issueRepo.countIssues(t.org.id, t.project.id)).toBe(0);
    expect(issueRepo.findIssueImport(t.org.id, batch.importKey)).toBeNull();
    expect((await consumeRateLimit(t.org.id, "issue:create")).allowed).toBe(true);
    resetRateLimits();
    await importIssues(t.actors.member, batch);
    expect((await consumeRateLimit(t.org.id, "issue:create", 59)).allowed).toBe(false);
  });

  it("applies scope, project lookup, archive and create permission gates", async () => {
    const t = await createTenant("import-access");
    const batch = input(t, "access-key", [{ title: "Never imported" }]);
    await expect(importIssues(tenant.actors.member, batch)).rejects.toBeInstanceOf(TenantScopeError);
    await expect(importIssues(t.actors.viewer, batch)).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(importIssues(t.actors.member, { ...batch, projectId: tenant.project.id })).rejects.toBeInstanceOf(NotFoundError);
    await expect(importIssues(t.actors.member, { ...batch, projectId: "missing" as ProjectId })).rejects.toBeInstanceOf(NotFoundError);
    const { projects } = await import("@/server/db");
    getDb().update(projects).set({ archivedAt: t.org.createdAt }).where(eq(projects.id, t.project.id)).run();
    await expect(importIssues(t.actors.member, batch)).rejects.toBeInstanceOf(AlreadyArchivedError);
    expect(await issueRepo.countIssues(t.org.id, t.project.id)).toBe(0);
  });
