export async function listIssues(
  actor: Actor,
  input: IssueFilterInput,
): Promise<Page<Issue>> {
  assertOrgScope(actor, input.orgId);
  // A cross-project list is an org-wide read; per-project visibility is
  // enforced when the caller opens an individual issue.
  assertCan(actor, "issue:read", orgResource(input.orgId));
  return issueRepo.listIssues(input);
}

export async function getBoard(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly IssueBoardColumn[]> {
  assertOrgScope(actor, orgId);

  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "issue:read", projectResource(project));

  return issueRepo.listBoardColumns(orgId, projectId);
}

export async function importIssues(actor: Actor, input: ImportIssuesInput): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);
  const project = requireFound(await projectRepo.findProjectById(input.orgId, input.projectId), "Project", input.projectId);
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  return serializeImport(input.orgId, async () => {
    const replay = issueRepo.findIssueImport(input.orgId, input.importKey);
    if (replay) return replay;
    input = importIssuesSchema.parse(input);
    const org = requireFound(await orgRepo.findOrgById(input.orgId), "Organization", input.orgId);
    const assertQuota = (used: number) => {
      if (wouldExceedLimit(org.plan, "issuesPerProject", used, input.rows.length)) {
        throw new Error(`Plan ${org.plan} allows no more issues in project ${project.key}`);
      }
    };
    assertQuota(await issueRepo.countIssues(input.orgId, input.projectId));
    setOrgPlan(input.orgId, org.plan);
    const verdict = await consumeRateLimit(input.orgId, "issue:create", input.rows.length);
    if (!verdict.allowed) {
      throw new Error(`Issue rate limit reached; try again after ${verdict.resetAt}`);
    }
    const result = issueRepo.insertIssueImport(input, actor.userId, assertQuota);
    if (!result.replayed) {
      await emit("issues.imported", {
        ...actorEnvelope(actor),
        projectId: result.projectId,
        importKey: result.importKey,
        issueIds: result.issues.map((issue) => issue.id),
      });
    }
    return result;
  });
}

/** Serializes workspace uploads so simultaneous retries share a result and never spend twice. */
const pendingImports = new Map<OrgId, Promise<void>>();

async function serializeImport<T>(orgId: OrgId, run: () => Promise<T>): Promise<T> {
  const preceding = pendingImports.get(orgId) ?? Promise.resolve();
  let release!: () => void;
  const pending = new Promise<void>((resolve) => { release = resolve; });
  pendingImports.set(orgId, pending);
  await preceding;
  try {
    return await run();
  } finally {
    release();
    if (pendingImports.get(orgId) === pending) pendingImports.delete(orgId);
  }
}
